<template>
  <div :style="{height:'100%',width:'100%'}" ref="wml-editor">
    <div :id="id" type="text/plain" :style="{height:'100%',width:'100%'}"></div>
  </div>
</template>

<script>
export default {
  name: 'WmlEditor',
  props: {
    id: {
      type: String,
      default: () => {
        let len = 32
        let chars = 'ABCDEFGHJKMNPQRSTWXYZabcdefhijkmnprstwxyz2345678'
        let str = ''
        for (let i = 0; i < len; i++) {
          str += chars.charAt(Math.floor(Math.random() * chars.length))
        }
        return str
      }
    },
    value: {
      type: String,
      default: ''
    },
    config: {
      type: Object,
      default: () => {
        return {
          labelMap: {
            wmlcustom: '外贸狼工具'
          }
        }
      }
    },
    height: {
      type: Number,
      default: 500
    }
  },
  data: () => {
    return {
      editor: null,
      content: null
    }
  },
  beforeUpdate () {

  },
  mounted () {
    const self = this
    self.$nextTick(() => {
      self.editor = window.UE.getEditor(self.id, self.config)
      self.editor.commands['mycard'] = {
        execCommand: function () {
          this.execCommand('insertHtml', '<p>自定义插件，我的名片</p>')
          return true
        },
        queryCommandState: function () {

        }
      }

      // var option = {
      //   initialContent: 'hello world',
      //   minFrameHeight: 200,
      //   iframeCssUrl: 'res/ueditor/themes/default/iframe.css'
      // }
      // var editor = new self.editor.ui.Editor(option)
      // editor.render('myEditor')

      self.editor.on('contentChange', function (e) {
        self.$emit('input', self.editor.getContent())
        self.$emit('getContent', self.editor.getContent())
      })
      const tempEditorH = self.$refs['wml-editor'].clientHeight
      console.log(tempEditorH)

      // self.editor.setHeight(tempEditorH)
      self.editor.ready(() => {
        self.editor.setContent(self.value, {
          autoHeightEnabled: false,
          initialFrameHeight: tempEditorH
        })
        self.editor.setHeight(self.height)
      })
      document.addEventListener('DOMSubtreeModified', () => {
        return (() => {
          const tempEditorH = self.$refs['wml-editor'].clientHeight

          self.editor.setOpt({ initialFrameHeight: tempEditorH })
        })()
      })
    })
  },
  methods: {
    getId () {
      return this.id
    },
    getContent () {
      return this.editor.getContent()
    },
    getEditor () {
      return this.editor
    }

  },
  destoryed () {
    this.editor.destroy()
  },
  watch: {
    value (e) {
    }
  }
}
</script>

